from __future__ import annotations

import logging
import re
from contextlib import contextmanager

from taf.ul.bts_components import Bbmod, Smod


def find_cpue_on_gnb(gnb_data: dict[str, str], logger: logging.Logger) -> list[dict[str, str]]:
    ipv6_regexp = re.compile(
        r"CPUE(\w+).*?((?:[A-F0-9]{1,4}:){7}[A-F0-9]{1,4})",
        re.IGNORECASE | re.MULTILINE | re.DOTALL,
    )
    cpues = []
    with get_smod_connection(gnb_data, logger) as smod_conn:
        bbmods_data = get_bbmods_data_from_gnb(smod_conn)
        smod_alias = smod_conn.get_alias()
        for bbmod_data in bbmods_data:
            with get_bbmod_connection(bbmod_data, smod_alias, logger) as bbmod_conn:
                cmd = "ip a | grep -i cpue -A 2"
                logger.debug(f"Executing command {cmd} on bbmod {bbmod_data['address']}")
                try:
                    output = bbmod_conn.execute(cmd, timeout=1)
                    for match in ipv6_regexp.finditer(output):
                        cpues.append(
                            {
                                "cpue_id": match.group(1),
                                "cpue_ip": match.group(2),
                                "cu_ip": gnb_data["cu_ip"],
                                "user": gnb_data["user"],
                                "password": gnb_data["password"],
                            }
                        )
                    logger.debug(output)
                except Exception as e:
                    logger.debug(e)
    return cpues


def get_bbmods_data_from_gnb(smod_conn: Smod) -> list[dict[str, str]]:
    bbmods_topology_info = smod_conn.get_bbmods_topology_info(get_other_cpus_info=True)
    return bbmods_topology_info


@contextmanager
def get_smod_connection(gnb_data: dict[str, str], logger: logging.Logger) -> Smod:
    smod = Smod()
    try:
        smod.connect_to(address=gnb_data["cu_ip"], username=gnb_data["user"], password=gnb_data["password"])
        yield smod
    finally:
        try:
            smod.close_connection()
            logger.debug("Disconnected from Smod")
        except Exception as err:
            logger.exception(err)
            raise


@contextmanager
def get_bbmod_connection(bbmod_data: dict[str, str], smod_alias: str, logger: logging.Logger) -> Bbmod:
    bbmod = Bbmod()
    try:
        bbmod.connect_to(
            address=bbmod_data["address"],
            username=bbmod_data["username"],
            password=bbmod_data["password"],
            proxy=smod_alias,
        )
        yield bbmod
    finally:
        try:
            bbmod.close_connection()
            logger.debug("Disconnected from Bbmod")
        except Exception as err:
            logger.exception(err)
            raise
